$clients=reseller_client_companies($pdo,RESELLER_COMPANY_ID);$active=0;$blocked=0;foreach($clients as $c){in_array((string)$c['status'],['blocked','suspended'],true)?$blocked++:$active++;}
$st=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM saas_reseller_customer_charges WHERE reseller_company_id=? AND status='open'");$st->execute([RESELLER_COMPANY_ID]);$open=(float)$st->fetchColumn();
$st=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM saas_reseller_customer_charges WHERE reseller_company_id=? AND status='paid' AND paid_at>=DATE_FORMAT(CURRENT_DATE,'%Y-%m-01')");$st->execute([RESELLER_COMPANY_ID]);$received=(float)$st->fetchColumn();
revenda_layout_start('Visão geral','dashboard',$reseller);?>
<div class="cards"><div class="card"><span>Clientes</span><strong><?=count($clients)?></strong></div><div class="card"><span>Ativos</span><strong><?=$active?></strong></div><div class="card"><span>Bloqueados</span><strong><?=$blocked?></strong></div><div class="card"><span>A receber</span><strong><?=rev_money($open)?></strong></div></div>
