<div class="panel" style="margin-top:16px"><h2>Clientes recentes</h2><div class="table"><table><thead><tr><th>Empresa</th><th>Status</th><th>Cobranças abertas</th><th></th></tr></thead><tbody><?php foreach(array_slice(array_reverse($clients),0,8) as $c):?><tr><td><strong><?=rev_h((string)$c['name'])?></strong><br><span class="muted"><?=rev_h((string)($c['subdomain']??''))?></span></td><td><span class="pill"><?=rev_h((string)$c['status'])?></span></td><td><?=(int)$c['open_charges']?></td><td><a class="btn btn-ghost" href="/revenda/cliente.php?id=<?=(int)$c['id']?>">Gerenciar</a></td></tr><?php endforeach;?></tbody></table></div></div>
